from marshmallow import Schema, fields


def test_from_dict_rejects_field_class():
    """Passing a Field class (not instance) to Schema.from_dict should raise TypeError."""
    with pytest.raises(
        TypeError, match='Field for "foo" must be declared as a Field instance'
    ):
        Schema.from_dict({"foo": fields.Str})"}
